                  <Legend />
                  <Bar yAxisId="left" dataKey="layersLostM" name="Layers lost (M)" fill={NAVY} radius={[4, 4, 0, 0]} />
                  <Line yAxisId="right" type="monotone" dataKey="wholesaleHighUsd" name="Wholesale high" stroke={TEAL} strokeWidth={2} />
                  <Line yAxisId="right" type="monotone" dataKey="retailAvgUsd" name="Retail avg" stroke={AMBER} strokeWidth={2} />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </>
      )}

      <p className="text-[11px] leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

