                  <Line yAxisId="right" type="monotone" dataKey="retailAvgUsd" name="Retail avg" stroke={AMBER} strokeWidth={2} />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </>
      )}

      <p className="text-[11px] leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

