              </ScatterChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            Points in the lower-right (wholesale already falling, retail still
            rising) mark the classic shelf lag ??? visible in Feb???Mar 2025.
          </p>
        </ChartCard>
      )}

      {view === "episodes" && (
        <>
          <ChartCard
            title="HPAI episode ladder"
            subtitle="Peak dollars, lag weeks, and half-life of the unwind"
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={EPISODES}
                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `$${v}`}
                  />
                  <Tooltip />
                  <Legend />
                  <Bar
                    dataKey="wholesalePeakUsd"
                    name="Wholesale peak"
                    fill={TEAL}
                    radius={[4, 4, 0, 0]}
                  />
                  <Bar
                    dataKey="retailPeakUsd"
                    name="Retail peak"
                    fill={AMBER}
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
            <div className="mt-3 overflow-x-auto">
              <table className="w-full min-w-[520px] text-left text-sm">
                <thead>
                  <tr className="border-b border-slate-200 text-xs uppercase text-slate-500">
                    <th className="py-2 pr-3">Episode</th>
                    <th className="py-2 pr-3">Lag</th>
                    <th className="py-2 pr-3">Pass-through</th>
                    <th className="py-2 pr-3">W half-life</th>
                    <th className="py-2 pr-3">R half-life</th>
                    <th className="py-2">Layers lost</th>
                  </tr>
                </thead>
                <tbody>
                  {EPISODES.map((e) => (
                    <tr key={e.id} className="border-b border-slate-100">
                      <td className="py-2 pr-3 font-medium text-slate-800">
                        {e.label}
                      </td>
                      <td className="py-2 pr-3">{e.lagWeeks} wk</td>
                      <td className="py-2 pr-3">{e.passThroughPct}%</td>
                      <td className="py-2 pr-3">
                        {e.wholesaleHalfLifeWeeks} wk
                      </td>
                      <td className="py-2 pr-3">
                        {e.retailHalfLifeWeeks == null
                          ? "???"
                          : `${e.retailHalfLifeWeeks} wk`}
                      </td>
                      <td className="py-2">~{e.layerLossM}M</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </ChartCard>
          <ChartCard
            title="Layer losses vs price pressure"
            subtitle="Annual / crest tallies ??? not a causal regression"
          >
            <div className="h-[280px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={LOSS_PRESSURE}
                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="period" tick={{ fontSize: 11 }} />
                  <YAxis
                    yAxisId="left"
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "Layers M",
                      angle: -90,
                      position: "insideLeft",
                      fontSize: 10,
                    }}
                  />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `$${v}`}
                  />
                  <Tooltip />
                  <Legend />
                  <Bar
                    yAxisId="left"
                    dataKey="layersLostM"
                    name="Layers lost (M)"
                    fill={NAVY}
                    radius={[4, 4, 0, 0]}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="wholesaleHighUsd"
                    name="Wholesale high"
                    stroke={TEAL}
                    strokeWidth={2}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="retailAvgUsd"
                    name="Retail avg"
                    stroke={AMBER}
                    strokeWidth={2}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </>
      )}

      <p className="text-[11px] leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

